solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <map>
#include <string>
#include <vector>

struct RegionInfo { std::uint64_t base, size, allocationBase; std::uint32_t state, protect, type; };
struct Allocation { std::uint64_t base, size; std::uint32_t type; int regions; };
struct ModuleInfo { std::string name; std::uint64_t base, size; };

std::string protection(std::uint32_t protect)
{
    std::string text;
    switch (protect & 0xFF)
    {
    case 0x01: text = "---"; break;
    case 0x02: text = "r--"; break;
    case 0x04: case 0x08: text = "rw-"; break;
    case 0x10: text = "--x"; break;
    case 0x20: text = "r-x"; break;
    case 0x40: case 0x80: text = "rwx"; break;
    default: return "?";
    }
    if (protect & 0x100) text += " guard";
    return text;
}

bool readable(const RegionInfo& r)
{
    if (r.state != 0x1000 || (r.protect & 0x100)) return false;
    const std::string p{ protection(r.protect) };
    return !p.empty() && p[0] == 'r';
}

std::vector<Allocation> allocations(const std::vector<RegionInfo>& regions)
{
    std::map<std::uint64_t, Allocation> byBase;
    std::vector<RegionInfo> sorted{ regions };
    std::sort(sorted.begin(), sorted.end(), [](const RegionInfo& a, const RegionInfo& b) { return a.base < b.base; });
    for (const RegionInfo& r : sorted)
    {
        if (r.state == 0x10000) continue;
        auto it{ byBase.find(r.allocationBase) };
        if (it == byBase.end()) it = byBase.emplace(r.allocationBase, Allocation{ r.allocationBase, 0, r.type, 0 }).first;
        it->second.size = std::max(it->second.size, r.base + r.size - r.allocationBase);
        ++it->second.regions;
    }
    std::vector<Allocation> out;
    for (const auto& entry : byBase) out.push_back(entry.second);
    return out;
}

static std::string hex(std::uint64_t v)
{
    static const char* const HEX{ "0123456789abcdef" };
    std::string out;
    do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
    return "0x" + out;
}

std::string label(const std::vector<ModuleInfo>& modules, std::uint64_t address)
{
    for (const ModuleInfo& m : modules)
        if (address >= m.base && address - m.base < m.size) return m.name + "+" + hex(address - m.base);
    return hex(address);
}

unitTests:
constexpr std::uint32_t COMMIT{ 0x1000 }, RESERVE{ 0x2000 }, FREE{ 0x10000 }, IMAGE{ 0x1000000 }, PRIVATE{ 0x20000 };
static std::vector<RegionInfo> map()
{
    return {
        { 0x0, 0x10000, 0, FREE, 0x01, 0 },
        { 0x7FF600001000, 0x2000, 0x7FF600000000, COMMIT, 0x20, IMAGE },       // .text
        { 0x7FF600000000, 0x1000, 0x7FF600000000, COMMIT, 0x02, IMAGE },       // headers
        { 0x7FF600003000, 0x1000, 0x7FF600000000, COMMIT, 0x04, IMAGE },       // .data
        { 0x8F0000, 0xFC000, 0x8F0000, RESERVE, 0x00, PRIVATE },               // stack: reserved part
        { 0x9EC000, 0x1000, 0x8F0000, COMMIT, 0x104, PRIVATE },                // guard page
        { 0x9ED000, 0x3000, 0x8F0000, COMMIT, 0x04, PRIVATE },                 // committed stack
    };
}

TEST("protections") {
    CHECK_EQ(protection(0x20), std::string("r-x"));
    CHECK_EQ(protection(0x04), std::string("rw-"));
    CHECK_EQ(protection(0x104), std::string("rw- guard"));
    CHECK_EQ(protection(0x01), std::string("---"));
    CHECK_EQ(protection(0x80), std::string("rwx"));
    CHECK_EQ(protection(0x00), std::string("?"));
}
TEST("readable regions") {
    const auto m{ map() };
    CHECK(readable(m[1]));
    CHECK(readable(m[6]));
    CHECK(!readable(m[0]));
    CHECK(!readable(m[4]));
    CHECK(!readable(m[5]));
    CHECK(!readable(RegionInfo{ 0, 0x1000, 0, COMMIT, 0x10, PRIVATE }));
}
TEST("grouping into allocations") {
    const auto a{ allocations(map()) };
    CHECK_EQ(a.size(), 2u);
    if (a.size() != 2) return;
    CHECK_EQ(a[0].base, 0x8F0000ull); CHECK_EQ(a[0].size, 0x100000ull); CHECK_EQ(a[0].regions, 3); CHECK_EQ(a[0].type, PRIVATE);
    CHECK_EQ(a[1].base, 0x7FF600000000ull); CHECK_EQ(a[1].size, 0x4000ull); CHECK_EQ(a[1].regions, 3); CHECK_EQ(a[1].type, IMAGE);
}
TEST("labels") {
    const std::vector<ModuleInfo> mods{ { "game.exe", 0x7FF600000000, 0x4000 }, { "ntdll.dll", 0x7FFA00000000, 0x1F0000 } };
    CHECK_EQ(label(mods, 0x7FF6000011A2), std::string("game.exe+0x11a2"));
    CHECK_EQ(label(mods, 0x7FFA00000000), std::string("ntdll.dll+0x0"));
    CHECK_EQ(label(mods, 0x9ED010), std::string("0x9ed010"));
}

